describe('Itemised Receipt after Checkout', () => {
    beforeEach(() => {
        cy.visit('/checkout');
        cy.get('#checkout-button').click();
    });

    it('should display an itemised receipt after successful checkout', () => {
        cy.get('#payment-method').select('Credit Card');
        cy.get('#card-number').type('4111111111111111');
        cy.get('#expiry-date').type('12/25');
        cy.get('#cvv').type('123');
        cy.get('#submit-payment').click();

        cy.url().should('include', '/receipt');
        cy.get('.receipt-header').should('contain', 'Thank you for your purchase!');
        cy.get('.itemised-list').should('exist');
        cy.get('.itemised-list').children().should('have.length.greaterThan', 0);
    });

    it('should show an error message for invalid payment details', () => {
        cy.get('#payment-method').select('Credit Card');
        cy.get('#card-number').type('1234567812345678');
        cy.get('#expiry-date').type('01/20');
        cy.get('#cvv').type('123');
        cy.get('#submit-payment').click();

        cy.get('.error-message').should('be.visible').and('contain', 'Invalid payment details');
        cy.url().should('not.include', '/receipt');
    });
});
